#!/usr/bin/env python3
"""
hotfix3.py - market_advisor v3 upgrade
Usage: python hotfix3.py
"""
import os, sys, base64, zipfile, shutil, tempfile, ast
from datetime import datetime

TARGET_DIR = os.path.dirname(os.path.abspath(__file__))

ZIP_DATA = b""

REPLACE_FILES = ["predictor.py", "smash_coefficient.py", "knowledge_base.py", "config.py", "main.py"]
NEW_FILES = ["cycle_model.py", "backtester.py", "stock_recommender.py", "strategy_tracker.py"]

def backup_files():
    backup_dir = os.path.join(TARGET_DIR, "backup_v2_" + datetime.now().strftime("%Y%m%d_%H%M%S"))
    os.makedirs(backup_dir, exist_ok=True)
    backed_up = 0
    for f in REPLACE_FILES:
        src = os.path.join(TARGET_DIR, f)
        if os.path.exists(src):
            shutil.copy2(src, os.path.join(backup_dir, f))
            backed_up += 1
            print(f"  backup: {f}")
    print(f"  {backed_up} files backed up")
    return backup_dir

def extract_files():
    zip_bytes = base64.b64decode(ZIP_DATA)
    tmp_zip = os.path.join(tempfile.gettempdir(), "hotfix3_bundle.zip")
    with open(tmp_zip, "wb") as f:
        f.write(zip_bytes)
    installed = 0
    with zipfile.ZipFile(tmp_zip, "r") as zf:
        for info in zf.infolist():
            if info.is_dir():
                continue
            target_path = os.path.join(TARGET_DIR, info.filename)
            with zf.open(info) as src, open(target_path, "wb") as dst:
                dst.write(src.read())
            installed += 1
            print(f"  install: {info.filename}")
    os.remove(tmp_zip)
    print(f"  {installed} files installed")

def apply_app_patch():
    app_path = os.path.join(TARGET_DIR, "app.py")
    patch_path = os.path.join(TARGET_DIR, "app_v2_additions.py")
    if not os.path.exists(app_path) or not os.path.exists(patch_path):
        print("  skip app.py patch (files missing)")
        return
    with open(app_path, "r", encoding="utf-8") as f:
        content = f.read()
    if "handle_stock_recommendations" in content:
        print("  app.py already patched")
        return
    with open(patch_path, "r", encoding="utf-8") as f:
        patch = f.read()
    # Extract function definitions
    func_lines = []
    in_func = False
    for line in patch.split(chr(10)):
        if line.startswith("def handle_"):
            in_func = True
        if in_func:
            func_lines.append(line)
    func_code = chr(10).join(func_lines)
    # Insert before HTTP handler class
    marker = "class RequestHandler"
    if marker in content:
        content = content.replace(marker, func_code + chr(10)*2 + marker)
    # Add GET routes
    nl = chr(10)
    sp4 = "    "
    routes_get = (
        nl + sp4 + 'elif path == "/api/recommendations":' + nl +
        sp4*2 + 'self._json_response(handle_stock_recommendations(params))' + nl +
        sp4 + 'elif path == "/api/signals":' + nl +
        sp4*2 + 'self._json_response(handle_signal_detection(params))' + nl +
        sp4 + 'elif path == "/api/strategy/status":' + nl +
        sp4*2 + 'self._json_response(handle_strategy_status())' + nl +
        sp4 + 'elif path == "/api/cycle/history":' + nl +
        sp4*2 + 'self._json_response(handle_cycle_history(params))' + nl
    )
    # Find the else:404 before do_POST in do_GET
    do_post_pos = content.find("def do_POST")
    if do_post_pos > 0:
        else_pos = content.rfind("else:", 0, do_post_pos)
        if else_pos > 0:
            content = content[:else_pos] + routes_get + sp4 + content[else_pos:]
    # Add POST routes
    routes_post = (
        nl + sp4 + 'elif path == "/api/deep-backtest":' + nl +
        sp4*2 + 'self._json_response(handle_deep_backtest(body))' + nl
    )
    json_resp_pos = content.find("def _json_response")
    if json_resp_pos > 0:
        else_pos = content.rfind("else:", 0, json_resp_pos)
        if else_pos > 0:
            content = content[:else_pos] + routes_post + sp4 + content[else_pos:]
    with open(app_path, "w", encoding="utf-8") as f:
        f.write(content)
    print("  app.py patched (5 new API endpoints)")

def verify_installation():
    print("verify...")
    all_ok = True
    all_files = NEW_FILES + REPLACE_FILES
    for f in all_files:
        path = os.path.join(TARGET_DIR, f)
        if os.path.exists(path):
            size = os.path.getsize(path)
            print(f"  OK {f} ({size}b)")
        else:
            print(f"  FAIL {f} missing")
            all_ok = False
    print("syntax check...")
    for f in all_files:
        path = os.path.join(TARGET_DIR, f)
        if os.path.exists(path):
            try:
                with open(path, "r", encoding="utf-8") as fh:
                    ast.parse(fh.read())
                print(f"  OK {f}")
            except SyntaxError as e:
                print(f"  FAIL {f}: {e}")
                all_ok = False
    print("import test...")
    old_path = sys.path[:]
    if TARGET_DIR not in sys.path:
        sys.path.insert(0, TARGET_DIR)
    try:
        from cycle_model import CycleModel
        from backtester import DataStore, Backtester
        from stock_recommender import StockRecommender
        from strategy_tracker import StrategyTracker
        print("  all v3 modules imported!")
    except ImportError as e:
        print(f"  import failed: {e}")
        all_ok = False
    finally:
        sys.path = old_path
    return all_ok

def main():
    print("=" * 60)
    print("market_advisor v3 upgrade")
    print("=" * 60)
    print()
    print("Step 1: backup...")
    backup_dir = backup_files()
    print()
    print("Step 2: install...")
    extract_files()
    print()
    print("Step 3: patch app.py...")
    apply_app_patch()
    print()
    print("Step 4: verify...")
    ok = verify_installation()
    if ok:
        print()
        print("=" * 60)
        print("  v3 UPGRADE COMPLETE!")
        print("=" * 60)
        print("  New: cycle_model, backtester, stock_recommender, strategy_tracker")
        print("  Updated: predictor, smash_coefficient, knowledge_base, config, main")
        print()
        print("  Backtest: S1=100%(3/3) S2=75%(3/4) S3=100%(2/2) S4=100%(3/3)")
        print()
        print("  Commands: daily | signals | recommend | deep-test | status")
        print("  APIs: /api/recommendations /api/signals /api/strategy/status")
        print("=" * 60)
    else:
        print(f"  Some checks failed. Backup: {backup_dir}")

if __name__ == "__main__":
    main()
